// @module vendor-frontend | Vendora v1.0 | SPIT Mini Project AY 2026-27
import { UploadCloud, X } from 'lucide-react';
import { useEffect, useState } from 'react';
import { getErrorMessage, productAPI, vendorAPI } from '../../services/api';
const blank={name:'',category_id:'',description:'',price:'',original_price:'',stock_qty:0,is_active:true};
export default function AddProductPanel({ open, onClose, product, onSaved }) {
  const [form,setForm]=useState(blank); const [categories,setCategories]=useState([]); const [saving,setSaving]=useState(false); const [error,setError]=useState(''); const [fileName,setFileName]=useState('');
  useEffect(()=>{if(open)productAPI.categories().then(({data})=>setCategories(data.data)).catch(()=>{});},[open]);
  useEffect(()=>{setForm(product?{name:product.name,category_id:product.category_id,description:product.description||'',price:product.price,original_price:product.original_price||'',stock_qty:product.stock_qty,is_active:Boolean(product.is_active)}:blank);setError('');setFileName('');},[product,open]);
  const submit=async(e)=>{e.preventDefault();setError('');if(!form.name.trim()||!form.category_id||Number(form.price)<=0||Number(form.stock_qty)<0){setError('Complete the required fields with valid values.');return;}setSaving(true);try{const payload={...form,category_id:Number(form.category_id),price:Number(form.price),original_price:form.original_price?Number(form.original_price):null,stock_qty:Number(form.stock_qty),is_active:Boolean(form.is_active)};if(product)await vendorAPI.updateProduct(product.product_id,payload);else await vendorAPI.createProduct(payload);await onSaved?.();onClose();}catch(err){setError(getErrorMessage(err,'Could not save product.'));}finally{setSaving(false);}};
  return <><div onClick={onClose} className={`fixed inset-0 z-50 bg-slate-950/30 backdrop-blur-sm transition ${open?'visible opacity-100':'invisible opacity-0'}`}/><aside className={`fixed right-0 top-0 z-[60] h-full w-full max-w-lg overflow-y-auto bg-white p-6 shadow-2xl transition-transform duration-300 ${open?'translate-x-0':'translate-x-full'}`}><div className="flex items-center justify-between"><div><h2 className="text-xl font-black text-slate-950">{product?'Edit product':'Add product'}</h2><p className="text-sm text-slate-500">Keep your catalog accurate and sellable.</p></div><button onClick={onClose} className="rounded-xl p-2 hover:bg-slate-100"><X className="h-5 w-5"/></button></div><form onSubmit={submit} className="mt-7 space-y-4"><label className="block"><span className="mb-1 block text-xs font-bold text-slate-600">Product Name</span><input className="input" value={form.name} onChange={(e)=>setForm({...form,name:e.target.value})} required/></label><label className="block"><span className="mb-1 block text-xs font-bold text-slate-600">Category</span><select className="input" value={form.category_id} onChange={(e)=>setForm({...form,category_id:e.target.value})} required><option value="">Select category</option>{categories.map((c)=><option key={c.category_id} value={c.category_id}>{c.emoji} {c.name}</option>)}</select></label><label className="block"><span className="mb-1 block text-xs font-bold text-slate-600">Description</span><textarea className="input min-h-28" value={form.description} onChange={(e)=>setForm({...form,description:e.target.value})}/></label><div className="grid grid-cols-2 gap-4"><label><span className="mb-1 block text-xs font-bold text-slate-600">Price</span><div className="relative"><span className="absolute left-3 top-2.5 text-slate-400">₹</span><input className="input pl-7" type="number" min="0.01" step="0.01" value={form.price} onChange={(e)=>setForm({...form,price:e.target.value})} required/></div></label><label><span className="mb-1 block text-xs font-bold text-slate-600">Original Price</span><input className="input" type="number" min="0" step="0.01" value={form.original_price} onChange={(e)=>setForm({...form,original_price:e.target.value})}/></label></div><label className="block"><span className="mb-1 block text-xs font-bold text-slate-600">Stock Qty</span><input className="input" type="number" min="0" value={form.stock_qty} onChange={(e)=>setForm({...form,stock_qty:e.target.value})}/></label><label className="block cursor-pointer rounded-2xl border-2 border-dashed border-slate-200 bg-slate-50 p-5 text-center hover:border-violet-300"><UploadCloud className="mx-auto h-6 w-6 text-violet-500"/><span className="mt-2 block text-sm font-semibold text-slate-700">{fileName||'Choose product image (UI preview only)'}</span><span className="text-xs text-slate-400">The fixed academic schema does not store image URLs.</span><input type="file" accept="image/*" className="hidden" onChange={(e)=>setFileName(e.target.files?.[0]?.name||'')}/></label><div className="flex items-center justify-between rounded-xl border border-slate-200 p-3"><div><p className="text-sm font-semibold">Product status</p><p className="text-xs text-slate-400">Active products appear in the public catalog.</p></div><button type="button" onClick={()=>setForm({...form,is_active:!form.is_active})} className={`relative h-7 w-12 rounded-full ${form.is_active?'bg-violet-600':'bg-slate-300'}`}><span className={`absolute top-1 h-5 w-5 rounded-full bg-white transition-all ${form.is_active?'left-6':'left-1'}`}/></button></div>{error&&<p className="text-sm text-red-600">{error}</p>}<button disabled={saving} className="w-full rounded-xl bg-slate-900 px-4 py-3 font-bold text-white hover:bg-violet-600 disabled:opacity-50">{saving?'Saving…':product?'Save Changes':'Create Product'}</button></form></aside></>;
}
